/* ============================== DESIGN TOKENS ============================== */
const COLORS = {
  bg: "#0A0E13",
  panel: "#11161D",
  panelAlt: "#0D1218",
  border: "#212A35",
  borderLight: "#2C3745",
  text: "#E7EDF3",
  textDim: "#8A96A5",
  textFaint: "#4E5A68",
  accent: "#5B8DEF",
  Critical: "#FF4D5E",
  High: "#FF9F43",
  Medium: "#F0C24B",
  Low: "#3FCDBA",
};

const SEVERITY_ORDER = ["Critical", "High", "Medium", "Low"];

const FEATURE_META = {
  after_hours_login: { label: "Off-hours login", icon: Clock, cat: "auth" },
  failed_logins: { label: "Failed logins", icon: ShieldAlert, cat: "auth" },
  distinct_ips: { label: "Multiple source IPs", icon: Globe, cat: "auth" },
  files_accessed: { label: "File access volume", icon: FileText, cat: "file" },
  sensitive_files_accessed: { label: "Sensitive folder access", icon: Lock, cat: "file" },
  files_downloaded: { label: "File downloads", icon: Download, cat: "file" },
  usb_first_time: { label: "First-time USB device", icon: Usb, cat: "usb" },
  usb_data_mb: { label: "USB data volume", icon: Usb, cat: "usb" },
  transfer_mb: { label: "Data transfer volume", icon: UploadCloud, cat: "transfer" },
  external_transfer_mb: { label: "External data transfer", icon: UploadCloud, cat: "transfer" },
};

const CAT_COLOR = {
  auth: "#5B8DEF",
  file: "#3FCDBA",
  usb: "#B98CE8",
  transfer: "#FF9F43",
};

/* ============================== HELPERS ============================== */
function fmtHour(h) {
  if (h === null || h === undefined || Number.isNaN(h)) return "n/a";
  const hh = Math.floor(h);
  const mm = Math.round((h - hh) * 60);
  return `${String(hh).padStart(2, "0")}:${String(mm).padStart(2, "0")}`;
}

function severityColor(sev) {
  return COLORS[sev] || COLORS.textDim;
}

/* ============================== RISK GAUGE ============================== */
function RiskGauge({ score, severity, size = 108 }) {
  const r = 46;
  const c = 2 * Math.PI * r;
  const pct = Math.max(0, Math.min(100, score));
  const offset = c - (pct / 100) * c;
  const color = severityColor(severity);
  return (
    <svg width={size} height={size} viewBox="0 0 120 120">
      <circle cx="60" cy="60" r={r} fill="none" stroke={COLORS.border} strokeWidth="10" />
      <circle
        cx="60" cy="60" r={r} fill="none" stroke={color} strokeWidth="10"
        strokeDasharray={c} strokeDashoffset={offset} strokeLinecap="round"
        transform="rotate(-90 60 60)"
        style={{ transition: "stroke-dashoffset 0.6s ease" }}
      />
      <text x="60" y="56" textAnchor="middle" fontSize="26" fontWeight="700"
        fill={COLORS.text} fontFamily="'IBM Plex Mono', monospace">
        {Math.round(score)}
      </text>
      <text x="60" y="76" textAnchor="middle" fontSize="10" letterSpacing="1.5"
        fill={COLORS.textDim} fontFamily="'IBM Plex Mono', monospace">
        RISK
      </text>
    </svg>
  );
}

/* ============================== RISK COMPOSITION BAR (signature element) ============================== */
function RiskCompositionBar({ reasons }) {
  const total = reasons.reduce((s, r) => s + r.contribution, 0) || 1;
  return (
    <div>
      <div style={{
        display: "flex", height: 10, borderRadius: 5, overflow: "hidden",
        border: `1px solid ${COLORS.border}`, background: COLORS.panelAlt,
      }}>
        {reasons.map((r, i) => {
          const meta = FEATURE_META[r.feature] || {};
          const width = (r.contribution / total) * 100;
          return (
            <div key={i} title={`${meta.label || r.feature}: ${r.contribution.toFixed(1)} pts`}
              style={{ width: `${width}%`, background: CAT_COLOR[meta.cat] || COLORS.accent, minWidth: 2 }} />
          );
        })}
      </div>
      <div style={{ display: "flex", gap: 14, marginTop: 8, flexWrap: "wrap" }}>
        {Object.entries(CAT_COLOR).map(([cat, color]) => (
          <div key={cat} style={{ display: "flex", alignItems: "center", gap: 5 }}>
            <div style={{ width: 8, height: 8, borderRadius: 2, background: color }} />
            <span style={{ fontSize: 10.5, color: COLORS.textDim, textTransform: "uppercase", letterSpacing: 0.5 }}>
              {cat === "auth" ? "Login/Auth" : cat === "file" ? "File Access" : cat === "usb" ? "USB" : "Data Transfer"}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ============================== SEVERITY BADGE ============================== */
function SeverityBadge({ severity, size = "md" }) {
  const color = severityColor(severity);
  const pad = size === "sm" ? "2px 8px" : "4px 11px";
  const fs = size === "sm" ? 10.5 : 12;
  return (
    <span style={{
      color, border: `1px solid ${color}55`, background: `${color}18`,
      borderRadius: 5, padding: pad, fontSize: fs, fontWeight: 700,
      letterSpacing: 0.6, textTransform: "uppercase", fontFamily: "'IBM Plex Mono', monospace",
      whiteSpace: "nowrap",
    }}>
      {severity}
    </span>
  );
}

/* ============================== ALERT LIST CARD ============================== */
function AlertCard({ alert, active, onClick }) {
  const topReason = alert.reasons[0];
  const meta = topReason ? FEATURE_META[topReason.feature] : null;
  const Icon = meta ? meta.icon : Activity;
  return (
    <button onClick={onClick} style={{
      display: "block", width: "100%", textAlign: "left", cursor: "pointer",
      background: active ? COLORS.panelAlt : "transparent",
      border: "none", borderLeft: `3px solid ${active ? severityColor(alert.severity) : "transparent"}`,
      borderBottom: `1px solid ${COLORS.border}`, padding: "12px 16px", transition: "background 0.15s",
    }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
            <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 13, fontWeight: 600, color: COLORS.text }}>
              {alert.user_id}
            </span>
            <span style={{ fontSize: 11, color: COLORS.textFaint }}>{alert.department}</span>
          </div>
          <div style={{ fontSize: 11.5, color: COLORS.textDim, fontFamily: "'IBM Plex Mono', monospace" }}>
            {alert.date}
          </div>
        </div>
        <SeverityBadge severity={alert.severity} size="sm" />
      </div>
      {topReason && (
        <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 8, color: COLORS.textDim, fontSize: 12 }}>
          <Icon size={13} color={CAT_COLOR[meta.cat]} />
          <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {topReason.explanation}
          </span>
        </div>
      )}
      <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 8 }}>
        <div style={{ flex: 1, height: 4, borderRadius: 2, background: COLORS.border, overflow: "hidden" }}>
          <div style={{ width: `${alert.risk_score}%`, height: "100%", background: severityColor(alert.severity) }} />
        </div>
        <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 11, color: COLORS.textDim, minWidth: 28, textAlign: "right" }}>
          {alert.risk_score.toFixed(0)}
        </span>
      </div>
    </button>
  );
}

/* ============================== EVIDENCE GRID ============================== */
function EvidenceGrid({ evidence }) {
  const items = [
    { label: "Earliest login", value: fmtHour(evidence.earliest_login_hour) },
    { label: "Failed logins", value: evidence.failed_logins },
    { label: "Files accessed", value: evidence.files_accessed },
    { label: "Sensitive files accessed", value: evidence.sensitive_files_accessed },
    { label: "Files downloaded", value: evidence.files_downloaded },
    { label: "USB events", value: evidence.usb_events },
    { label: "First-time USB devices", value: evidence.usb_first_time },
    { label: "USB data written", value: `${evidence.usb_data_mb.toFixed(0)} MB` },
    { label: "Total data transfer", value: `${evidence.transfer_mb.toFixed(0)} MB` },
    { label: "External transfer", value: `${evidence.external_transfer_mb.toFixed(0)} MB` },
  ];
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 1, background: COLORS.border, border: `1px solid ${COLORS.border}`, borderRadius: 8, overflow: "hidden" }}>
      {items.map((it, i) => (
        <div key={i} style={{ background: COLORS.panel, padding: "9px 12px" }}>
          <div style={{ fontSize: 10.5, color: COLORS.textFaint, textTransform: "uppercase", letterSpacing: 0.5 }}>{it.label}</div>
          <div style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 14, color: COLORS.text, marginTop: 2 }}>{it.value}</div>
        </div>
      ))}
    </div>
  );
}

/* ============================== TIMELINE CHART ============================== */
function UserTimeline({ userId, highlightDate }) {
  const data = TIMELINES[userId] || [];
  if (!data.length) return null;
  return (
    <div>
      <ResponsiveContainer width="100%" height={140}>
        <LineChart data={data} margin={{ top: 6, right: 8, left: -20, bottom: 0 }}>
          <CartesianGrid stroke={COLORS.border} strokeDasharray="2 4" vertical={false} />
          <ReferenceArea y1={80} y2={100} fill={COLORS.Critical} fillOpacity={0.06} />
          <ReferenceArea y1={60} y2={80} fill={COLORS.High} fillOpacity={0.05} />
          <XAxis dataKey="d" tick={{ fill: COLORS.textFaint, fontSize: 9.5 }} interval={6}
            axisLine={{ stroke: COLORS.border }} tickLine={false} />
          <YAxis domain={[0, 100]} tick={{ fill: COLORS.textFaint, fontSize: 9.5 }}
            axisLine={false} tickLine={false} width={26} />
          <Tooltip
            contentStyle={{ background: COLORS.panelAlt, border: `1px solid ${COLORS.border}`, borderRadius: 6, fontSize: 11.5 }}
            labelStyle={{ color: COLORS.textDim }}
            itemStyle={{ color: COLORS.text }}
            formatter={(v) => [v.toFixed ? v.toFixed(1) : v, "risk score"]}
          />
          {highlightDate && (
            <ReferenceLine x={highlightDate.slice(5)} stroke={COLORS.accent} strokeDasharray="3 3" />
          )}
          <Line type="monotone" dataKey="r" stroke={COLORS.accent} strokeWidth={1.8} dot={false} />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

/* ============================== DETAIL PANEL ============================== */
function DetailPanel({ alert, onClose }) {
  if (!alert) {
    return (
      <div style={{
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
        height: "100%", color: COLORS.textFaint, gap: 10,
      }}>
        <Radio size={28} strokeWidth={1.3} />
        <div style={{ fontSize: 13 }}>Select an alert to review evidence</div>
      </div>
    );
  }
  return (
    <div style={{ padding: 24, overflowY: "auto", height: "100%" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 20 }}>
        <div>
          <div style={{ fontSize: 11, color: COLORS.textFaint, fontFamily: "'IBM Plex Mono', monospace", letterSpacing: 1 }}>
            {alert.alert_id}
          </div>
          <div style={{ fontSize: 20, fontWeight: 700, color: COLORS.text, marginTop: 2, display: "flex", alignItems: "center", gap: 10 }}>
            {alert.user_id}
            <span style={{ fontSize: 13, fontWeight: 400, color: COLORS.textDim }}>· {alert.department}</span>
          </div>
          <div style={{ fontSize: 12.5, color: COLORS.textDim, marginTop: 3, fontFamily: "'IBM Plex Mono', monospace" }}>
            {alert.date}
            {!alert.baseline_ready && (
              <span style={{ marginLeft: 10, color: COLORS.Medium }}>· provisional (baseline still forming)</span>
            )}
          </div>
        </div>
        <button onClick={onClose} style={{ background: "none", border: "none", color: COLORS.textFaint, cursor: "pointer" }}>
          <X size={18} />
        </button>
      </div>

      <div style={{ display: "flex", gap: 20, alignItems: "center", marginBottom: 24 }}>
        <RiskGauge score={alert.risk_score} severity={alert.severity} />
        <div>
          <SeverityBadge severity={alert.severity} />
          <div style={{ fontSize: 11.5, color: COLORS.textDim, marginTop: 8, lineHeight: 1.5 }}>
            Isolation Forest anomaly percentile:{" "}
            <span style={{ color: COLORS.text, fontFamily: "'IBM Plex Mono', monospace" }}>
              {alert.isolation_forest_score.toFixed(1)}
            </span>
            <br />
            {alert.reasons.length} contributing signal{alert.reasons.length !== 1 ? "s" : ""} detected
          </div>
        </div>
      </div>

      <SectionLabel>Why this was flagged</SectionLabel>
      <RiskCompositionBar reasons={alert.reasons} />
      <div style={{ marginTop: 14, display: "flex", flexDirection: "column", gap: 8 }}>
        {alert.reasons.map((r, i) => {
          const meta = FEATURE_META[r.feature] || {};
          const Icon = meta.icon || Activity;
          return (
            <div key={i} style={{
              display: "flex", gap: 10, alignItems: "flex-start", padding: "10px 12px",
              background: COLORS.panelAlt, border: `1px solid ${COLORS.border}`, borderRadius: 8,
            }}>
              <div style={{
                width: 26, height: 26, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center",
                background: `${CAT_COLOR[meta.cat]}22`, flexShrink: 0,
              }}>
                <Icon size={14} color={CAT_COLOR[meta.cat]} />
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 13, color: COLORS.text, lineHeight: 1.4 }}>{r.explanation}</div>
                <div style={{ fontSize: 10.5, color: COLORS.textFaint, marginTop: 3, fontFamily: "'IBM Plex Mono', monospace" }}>
                  +{r.contribution.toFixed(1)} pts · z={r.z_score.toFixed(1)}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <SectionLabel style={{ marginTop: 24 }}>Supporting evidence</SectionLabel>
      <EvidenceGrid evidence={alert.evidence} />

      <SectionLabel style={{ marginTop: 24 }}>60-day risk timeline — {alert.user_id}</SectionLabel>
      <div style={{ background: COLORS.panelAlt, border: `1px solid ${COLORS.border}`, borderRadius: 8, padding: "10px 6px 4px" }}>
        <UserTimeline userId={alert.user_id} highlightDate={alert.date} />
      </div>
    </div>
  );
}

function SectionLabel({ children, style }) {
  return (
    <div style={{
      fontSize: 11, fontWeight: 700, color: COLORS.textDim, textTransform: "uppercase",
      letterSpacing: 1, marginBottom: 10, ...style,
    }}>
      {children}
    </div>
  );
}

/* ============================== SUMMARY STRIP ============================== */
function SummaryStrip({ counts, total, users, days }) {
  return (
    <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
      {SEVERITY_ORDER.map((sev) => (
        <div key={sev} style={{
          display: "flex", alignItems: "center", gap: 8, padding: "7px 13px",
          background: COLORS.panel, border: `1px solid ${COLORS.border}`, borderRadius: 8,
        }}>
          <div style={{ width: 8, height: 8, borderRadius: "50%", background: severityColor(sev) }} />
          <span style={{ fontSize: 12, color: COLORS.textDim }}>{sev}</span>
          <span style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 13, fontWeight: 700, color: COLORS.text }}>
            {counts[sev] || 0}
          </span>
        </div>
      ))}
      <div style={{
        display: "flex", alignItems: "center", gap: 8, padding: "7px 13px",
        background: COLORS.panel, border: `1px solid ${COLORS.border}`, borderRadius: 8, marginLeft: "auto",
      }}>
        <Users size={13} color={COLORS.textDim} />
        <span style={{ fontSize: 12, color: COLORS.textDim }}>{users} users · {days} days monitored</span>
      </div>
    </div>
  );
}

/* ============================== MAIN APP ============================== */
export default function InsiderThreatDashboard() {
  const [severityFilter, setSeverityFilter] = useState(["Critical", "High", "Medium"]);
  const [search, setSearch] = useState("");
  const [selectedId, setSelectedId] = useState(ALERTS[0]?.alert_id || null);

  const filtered = useMemo(() => {
    return ALERTS.filter((a) => {
      if (!severityFilter.includes(a.severity)) return false;
      if (search && !a.user_id.toLowerCase().includes(search.toLowerCase()) &&
          !a.department.toLowerCase().includes(search.toLowerCase())) return false;
      return true;
    });
  }, [severityFilter, search]);

  const selected = ALERTS.find((a) => a.alert_id === selectedId) || null;

  function toggleSeverity(sev) {
    setSeverityFilter((prev) =>
      prev.includes(sev) ? prev.filter((s) => s !== sev) : [...prev, sev]
    );
  }

  return (
    <div style={{
      background: COLORS.bg, minHeight: "100vh", color: COLORS.text,
      fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, sans-serif",
      display: "flex", flexDirection: "column",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; }
        ::-webkit-scrollbar { width: 8px; height: 8px; }
        ::-webkit-scrollbar-thumb { background: ${COLORS.border}; border-radius: 4px; }
        ::-webkit-scrollbar-track { background: transparent; }
      `}</style>

      {/* Header */}
      <div style={{ borderBottom: `1px solid ${COLORS.border}`, padding: "16px 24px", background: COLORS.panel }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 14 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <div style={{
              width: 34, height: 34, borderRadius: 8, background: `${COLORS.accent}20`,
              display: "flex", alignItems: "center", justifyContent: "center",
            }}>
              <ShieldAlert size={18} color={COLORS.accent} />
            </div>
            <div>
              <div style={{ fontSize: 15.5, fontWeight: 700, letterSpacing: 0.3 }}>Insider Threat Detection</div>
              <div style={{ fontSize: 11, color: COLORS.textFaint, display: "flex", alignItems: "center", gap: 5 }}>
                <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#3FCDBA", display: "inline-block" }} />
                Behavioral baseline model · Isolation Forest engine active
              </div>
            </div>
          </div>
          <SummaryStrip counts={SUMMARY.severity_counts} total={SUMMARY.total_alerts} users={SUMMARY.users_monitored} days={SUMMARY.days_covered} />
        </div>
      </div>

      {/* Body */}
      <div style={{ flex: 1, display: "grid", gridTemplateColumns: "380px 1fr", minHeight: 0 }}>
        {/* Alert queue */}
        <div style={{ borderRight: `1px solid ${COLORS.border}`, display: "flex", flexDirection: "column", minHeight: 0 }}>
          <div style={{ padding: "14px 16px 10px", borderBottom: `1px solid ${COLORS.border}` }}>
            <div style={{ position: "relative", marginBottom: 10 }}>
              <Search size={14} color={COLORS.textFaint} style={{ position: "absolute", left: 10, top: 9 }} />
              <input
                value={search} onChange={(e) => setSearch(e.target.value)}
                placeholder="Search user or department…"
                style={{
                  width: "100%", background: COLORS.panelAlt, border: `1px solid ${COLORS.border}`,
                  borderRadius: 6, padding: "8px 10px 8px 30px", color: COLORS.text, fontSize: 12.5, outline: "none",
                }}
              />
            </div>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {SEVERITY_ORDER.map((sev) => {
                const active = severityFilter.includes(sev);
                return (
                  <button key={sev} onClick={() => toggleSeverity(sev)} style={{
                    fontSize: 10.5, fontWeight: 700, letterSpacing: 0.4, textTransform: "uppercase",
                    padding: "4px 9px", borderRadius: 5, cursor: "pointer",
                    fontFamily: "'IBM Plex Mono', monospace",
                    border: `1px solid ${active ? severityColor(sev) : COLORS.border}`,
                    background: active ? `${severityColor(sev)}18` : "transparent",
                    color: active ? severityColor(sev) : COLORS.textFaint,
                  }}>
                    {sev}
                  </button>
                );
              })}
            </div>
          </div>
          <div style={{ overflowY: "auto", flex: 1 }}>
            {filtered.length === 0 && (
              <div style={{ padding: 24, color: COLORS.textFaint, fontSize: 12.5, textAlign: "center" }}>
                No alerts match this filter.
              </div>
            )}
            {filtered.map((a) => (
              <AlertCard key={a.alert_id} alert={a} active={a.alert_id === selectedId}
                onClick={() => setSelectedId(a.alert_id)} />
            ))}
          </div>
        </div>

        {/* Detail */}
        <div style={{ minHeight: 0 }}>
          <DetailPanel alert={selected} onClose={() => setSelectedId(null)} />
        </div>
      </div>
    </div>
  );
}
